  1| //! Configuration: discovery, layered merge, and validation.
  2| //!
  3| //! A tinysweeper config is assembled from three layers, later winning:
  4| //!
  5| //! 1. [`DEFAULTS`], compiled into the binary
  6| //! 2. the named preset, if the repository asked for one
  7| //! 3. the repository's own `.tinysweeper.toml`
  8| //!
  9| //! The merge happens at the TOML level and records provenance per key, so
 10| //! `tinysweeper doctor` can say which layer set each effective value without
 11| //! anyone maintaining a second copy of that knowledge.
 12| 
 13| pub mod merge;
 14| pub mod remote;
 15| pub mod types;
 16| pub mod validate;
 17| 
 18| #[cfg(test)]
 19| mod test;
 20| 
 21| use std::path::{Path, PathBuf};
 22| 
 23| use toml::Table;
 24| 
 25| use crate::error::{Error, Result};
 26| 
 27| pub use crate::config::merge::{Layer, Provenance};
 28| pub use crate::config::types::{
 29|     AutoMerge, Automation, Cache, Config, IssueClose, Issues, Labeler, Labels, Lane, LaneId,
 30|     MergeMethod, ModelRef, Models, PathInstruction, Paths, Review, Sentry, Severity, Stale,
 31| };
 32| 
 33| /// The built-in defaults, compiled in so a repository with no config at all
 34| /// still gets a sane, conservative review.
 35| pub const DEFAULTS: &str = include_str!("defaults.toml");
 36| 
 37| /// Config file names, in the order they are searched for in a directory.
 38| pub const CONFIG_NAMES: [&str; 2] = [".tinysweeper.toml", ".github/tinysweeper.toml"];
 39| 
 40| /// Environment variable overriding where presets are read from. Set in the
 41| /// Docker image, where presets ship at a fixed path outside the checkout.
 42| pub const PRESETS_DIR_ENV: &str = "TINYSWEEPER_PRESETS_DIR";
 43| 
 44| /// A config file located on disk.
 45| #[derive(Debug, Clone, PartialEq, Eq)]
 46| pub struct Located {
 47|     /// The file that was found.
 48|     pub path: PathBuf,
 49| }
 50| 
 51| /// The result of loading a config: the effective values plus where each came
 52| /// from.
 53| #[derive(Debug, Clone)]
 54| pub struct Loaded {
 55|     /// The effective configuration.
 56|     pub config: Config,
 57|     /// Which layer set each key.
 58|     pub provenance: Provenance,
 59|     /// The repository config file, if one was found. Absent means the defaults
 60|     /// (plus any preset) are running unmodified.
 61|     pub source: Option<PathBuf>,
 62|     /// The preset file that was merged, if the config named one.
 63|     pub preset_source: Option<PathBuf>,
 64| }
 65| 
 66| /// Find a config file at or under `path`.
 67| ///
 68| /// `path` may be the file itself or a directory to search. Returns `None` when
 69| /// a directory contains no config — which is not an error: running on defaults
 70| /// is a supported mode.
 71| pub fn discover(path: &Path) -> Result<Option<Located>> {
 72|     if path.is_file() {
 73|         return Ok(Some(Located {
 74|             path: path.to_path_buf(),
 75|         }));
 76|     }
 77| 
 78|     if !path.is_dir() {
 79|         return Err(Error::path(path, "no such file or directory"));
 80|     }
 81| 
 82|     for name in CONFIG_NAMES {
 83|         let candidate = path.join(name);
 84|         if candidate.is_file() {
 85|             return Ok(Some(Located { path: candidate }));
 86|         }
 87|     }
 88| 
 89|     Ok(None)
 90| }
 91| 
 92| /// Load the effective configuration for the repository rooted at `root`.
 93| ///
 94| /// `explicit` overrides discovery when the caller passed `--config`.
