13| /// Build a repository skeleton with an optional config file and preset.
14| fn repo(config: Option<&str>, presets: &[(&str, &str)]) -> TempDir {
15|     let dir = tempfile::tempdir().expect("tempdir");
16|     if let Some(text) = config {
17|         std::fs::write(dir.path().join(".tinysweeper.toml"), text).expect("write config");
18|     }
19|     for (name, text) in presets {
20|         let preset_dir = dir.path().join("presets").join(name);
21|         std::fs::create_dir_all(&preset_dir).expect("create preset dir");
22|         std::fs::write(preset_dir.join("preset.toml"), text).expect("write preset");
23|     }
24|     dir
25| }
26| 
27| /// Write a rule document into a repository skeleton's `presets/rules/`.
28| fn with_rules(dir: &TempDir, name: &str, text: &str) {
29|     let rules_dir = dir.path().join("presets").join("rules");
30|     std::fs::create_dir_all(&rules_dir).expect("create rules dir");
31|     std::fs::write(rules_dir.join(format!("{name}.md")), text).expect("write rule document");
32| }
33| 
34| /// Copy this repository's own rule documents into a skeleton, so a shipped
35| /// preset that references one resolves.
36| fn with_shipped_rules(dir: &TempDir) {
37|     let source = Path::new(env!("CARGO_MANIFEST_DIR"))
38|         .join("presets")
39|         .join("rules");
40|     for entry in std::fs::read_dir(&source).expect("read shipped rules") {
41|         let entry = entry.expect("dir entry");
42|         if entry.path().extension().is_some_and(|e| e == "md") {
43|             let name = entry
44|                 .path()
45|                 .file_stem()
46|                 .unwrap()
47|                 .to_string_lossy()
48|                 .into_owned();
49|             with_rules(
50|                 dir,
51|                 &name,
52|                 &std::fs::read_to_string(entry.path()).expect("read rule document"),
53|             );
54|         }
55|     }
56| }
