780|     /// The lanes that will actually run, parsed and deduplicated.
781|     ///
782|     /// Unknown lane names are rejected by validation, so by the time anything
783|     /// calls this they cannot appear.
784|     pub fn enabled_lanes(&self) -> Vec<LaneId> {
785|         let mut lanes: Vec<LaneId> = self
786|             .review
787|             .lanes
788|             .iter()
789|             .filter_map(|name| LaneId::parse(name))
790|             .collect();
791|         lanes.sort_unstable();
792|         lanes.dedup();
793|         lanes
794|     }
795| 
796|     /// The severity at or above which findings are posted.
797|     ///
798|     /// From `strictness` unless the repository set it explicitly.
799|     pub fn severity_gate(&self) -> Severity {
800|         self.review
801|             .severity_gate
802|             .as_deref()
803|             .and_then(Severity::parse)
804|             .unwrap_or_else(|| self.strictness().severity)
805|     }
806| 
807|     /// The confidence a finding needs before it is posted.
808|     pub fn confidence_min(&self) -> f64 {
809|         self.review
810|             .confidence_min
811|             .unwrap_or_else(|| self.strictness().confidence)
812|     }
813| 
814|     /// The gates `review.strictness` implies.
815|     fn strictness(&self) -> Strictness {
816|         Strictness::for_level(self.review.strictness)
817|     }
818| 
819|     /// The lane-specific overrides for `lane`, if it has any.
820|     ///
821|     /// Keys are matched case-insensitively and untrimmed, because that is what
822|     /// validation accepts. Matching only the canonical spelling here would let
823|     /// `[lanes.Critique]` validate cleanly and then be silently ignored, which
824|     /// is the worst outcome available: the setting looks applied and is not.
825|     pub fn lane(&self, lane: LaneId) -> Option<&Lane> {
826|         self.lanes
827|             .iter()
828|             .find(|(key, _)| LaneId::parse(key) == Some(lane))
829|             .map(|(_, value)| value)
830|     }
831| 
832|     /// Resolve a lane's model to a concrete model id.
833|     ///
834|     /// A lane may name a tier (`scan`, `deep`) or an explicit id. Lanes with no
835|     /// override run on the `scan` tier, because the expensive tier should be an
836|     /// opt-in.
837|     pub fn model_for(&self, lane: LaneId) -> &str {
838|         let reference = self.lane(lane).and_then(|l| l.model.as_ref());
839|         match reference.map(|r| r.0.as_str()) {
840|             Some("deep") => &self.models.deep,
841|             Some("scan") | None => &self.models.scan,
842|             Some(explicit) => explicit,
843|         }
844|     }
845| 
846|     /// Resolve a non-lane [`Workload`] to a concrete model id.
847|     ///
848|     /// Every mechanical workload runs on the cheap tier, and the `match` is
849|     /// exhaustive on purpose: adding a workload should make someone state which
850|     /// tier it belongs to rather than inherit whichever one happens to be
851|     /// first. Repositories cannot override this the way they override a lane —
852|     /// paying deep-tier prices to copy a snippet out of a diff is not a
853|     /// trade-off worth exposing.
854|     pub fn model_for_workload(&self, workload: Workload) -> &str {
855|         match workload {
856|             Workload::Relocate
857|             | Workload::Falsify
858|             | Workload::KnowledgeExtraction
859|             | Workload::ThreadReview => &self.models.scan,
860|         }
861|     }
862| 
863|     /// Resolve the model issue triage runs on.
864|     ///
865|     /// Same three-way resolution as [`Config::model_for`] — a tier name, or an
866|     /// explicit id passed through untouched — but read from `[issues]`, which
867|     /// is not a lane and so has no entry in `review.lanes`.
868|     pub fn model_for_issues(&self) -> &str {
869|         match self.issues.model.as_ref().map(|r| r.0.as_str()) {
870|             Some("deep") => &self.models.deep,
871|             Some("scan") | None => &self.models.scan,
872|             Some(explicit) => explicit,
873|         }
874|     }
875| 
876|     /// The severity at which a review blocks the merge, if it ever does.
877|     pub fn request_changes_at(&self) -> Option<Severity> {
878|         let setting = self.review.request_changes_at.trim();
879|         if setting.eq_ignore_ascii_case("off") || setting.is_empty() {
880|             return None;
881|         }
882|         Severity::parse(setting)
883|     }
884| 
885|     /// The severity at which `lane` fails its check run.
886|     pub fn fail_on(&self, lane: LaneId) -> Severity {
887|         self.lane(lane)
888|             .and_then(|l| l.fail_on.as_deref())
889|             .and_then(Severity::parse)
890|             .unwrap_or(Severity::High)
891|     }
892| }
