 51| fn validate_review(config: &Config, problems: &mut Vec<String>) {
 52|     let review = &config.review;
 53| 
 54|     if review.lanes.is_empty() {
 55|         problems.push("`review.lanes` is empty; nothing would run".into());
 56|     }
 57|     for name in &review.lanes {
 58|         // `gate` gets its own message below. Falling through to "unknown lane"
 59|         // as well would tell someone whose config predates the change that they
 60|         // made a typo, and then separately that they did not.
 61|         if LaneId::parse(name).is_none() && name.trim() != "gate" {
 62|             problems.push(format!(
 63|                 "`review.lanes` contains unknown lane `{name}`; expected one of {}",
 64|                 known(&LaneId::ALL.map(|l| l.as_str()))
 65|             ));
 66|         }
 67|     }
 68|     // `gate` was a lane once. It published `tinysweeper/gate`, an aggregate of
 69|     // every other lane, and it is gone: the same verdict now arrives as the
 70|     // bot's own review, which is what branch protection should require.
 71|     // Named explicitly rather than falling through to "unknown lane", because
 72|     // a configuration carried over from before the change deserves to be told
 73|     // what replaced it rather than that it made a typo.
 74|     if review.lanes.iter().any(|l| l.trim() == "gate") {
 75|         problems.push(
 76|             "`review.lanes` lists `gate`; the aggregate check run no longer exists — \
 77|              the bot's approving review carries that verdict now, so remove it"
 78|                 .into(),
 79|         );
 80|     }
 81| 
 82|     if !(1..=3).contains(&review.strictness) {
 83|         problems.push(format!(
 84|             "`review.strictness = {}` is out of range; expected 1 (chill), 2 (default) or 3 (assertive)",
 85|             review.strictness
 86|         ));
 87|     }
 88| 
 89|     if let Some(gate) = &review.severity_gate
 90|         && Severity::parse(gate).is_none()
 91|     {
 92|         problems.push(format!(
 93|             "`review.severity_gate = \"{gate}\"` is not a severity; expected one of {}",
 94|             known(&Severity::ALL.map(|s| s.as_str()))
 95|         ));
 96|     }
 97| 
 98|     if let Some(confidence) = review.confidence_min
 99|         && !(0.0..=1.0).contains(&confidence)
100|     {
101|         problems.push(format!(
102|             "`review.confidence_min = {confidence}` is out of range; expected 0.0 to 1.0"
103|         ));
104|     }
105| 
106|     let blocking = review.request_changes_at.trim();
107|     if !blocking.eq_ignore_ascii_case("off") && Severity::parse(blocking).is_none() {
108|         problems.push(format!(
109|             "`review.request_changes_at = \"{blocking}\"` is not a severity; expected `off` or one of {}",
110|             known(&Severity::ALL.map(|s| s.as_str()))
111|         ));
112|     }
113| 
114|     if review.max_comments == 0 {
115|         problems.push(
116|             "`review.max_comments = 0` would suppress every comment; set it above zero, or disable the lanes you do not want"
117|                 .into(),
118|         );
119|     }
120| }
