 15| //! finding by guessing or copying its fingerprint. Three things stop that:
 16| //!
 17| //! 1. A marker is only honoured on a comment **tinysweeper itself wrote**, by
 18| //!    login. A contributor cannot author a comment as the app.
 19| //! 2. A marker must be a well-formed fingerprint — sixteen lowercase hex
 20| //!    characters — so nothing else in a body is ever treated as one.
 21| //! 3. Suppression only removes a *duplicate comment*. Check-run conclusions and
 22| //!    the merge gate are computed before dedupe runs (see
 23| //!    `crate::app::review::lane_proposal`), so even a marker that somehow got
 24| //!    through hides a repeat comment and cannot unblock a merge.
 25| 
 26| use std::collections::BTreeSet;
 27| 
 28| use crate::error::Result;
 29| use crate::forge::types::RepoId;
 30| use crate::ports::forge::ForgeRead;
 31| 
 32| /// The marker key carrying a finding's fingerprint.
 33| const FINGERPRINT_KEY: &str = "fp=";
 34| 
 35| /// The marker key carrying the last reviewed head SHA.
 36| const STATE_KEY: &str = "state v=1 sha=";
 37| 
 38| /// The login tinysweeper posts as, unless the deployment says otherwise.
 39| ///
 40| /// Overridable because the GitHub App's slug decides the login, and a
 41| /// self-hosted install will not be called `tinysweeper`. Getting this wrong
 42| /// fails safe in the noisy direction — nothing is recognised as our own, so
 43| /// nothing is deduped — rather than in the direction that lets a stranger
 44| /// suppress findings.
 45| const BOT_LOGIN_ENV: &str = "TINYSWEEPER_BOT_LOGIN";
 46| 
 47| /// Everything an earlier cycle left behind on the pull request.
 48| #[derive(Debug, Clone, Default, PartialEq, Eq)]
 49| pub struct PriorReview {
 50|     /// Fingerprints of findings already posted as inline comments.
 51|     pub posted: BTreeSet<String>,
 52|     /// Titles of those findings, in the order they were found.
 53|     ///
 54|     /// This is prompt layer 4: what the model said last time, so it can verify
 55|     /// each one against the current code instead of starting over.
 56|     pub titles: Vec<String>,
 57|     /// The head SHA of the last review, when a marker recorded one.
 58|     pub last_sha: Option<String>,
 59| }
 60| 
 61| impl PriorReview {
 62|     /// Whether this finding has already been posted on the pull request.
 63|     pub fn already_posted(&self, identity: &str) -> bool {
 64|         self.posted.contains(identity)
 65|     }
 66| }
 67| 
 68| /// Whether `login` is the account tinysweeper posts as.
 69| ///
 70| /// A GitHub App comments as `<slug>[bot]`, so the suffix is stripped before
 71| /// comparing. The comparison is exact rather than a prefix match: `starts_with`
 72| /// would accept an account called `tinysweeper-evil`, which anyone can register
 73| /// and which would then be able to forge suppression markers.
 74| ///
 75| /// Returns false for empty login or empty configured bot login, failing safe
 76| /// rather than treating an unconfigured bot as anything.
 77| pub fn is_own_login(login: &str) -> bool {
 78|     let expected = std::env::var(BOT_LOGIN_ENV).unwrap_or_else(|_| "tinysweeper".to_string());
 79|     login_matches(login, &expected)
 80| }
 81| 
 82| /// The comparison itself, with the configured login passed in.
 83| ///
 84| /// Split from [`is_own_login`] so the security-critical half can be tested
 85| /// without touching the process environment. `set_var` is unsafe in Rust 2024
 86| /// precisely because it races every other thread reading the environment, and
 87| /// this crate's tests run in parallel — a test that mutated the variable could
 88| /// make an unrelated test read a login that was never configured for it.
 89| fn login_matches(login: &str, expected: &str) -> bool {
 90|     if login.is_empty() {
 91|         return false;
 92|     }
 93|     let trimmed = expected.trim();
 94|     if trimmed.is_empty() {
 95|         return false;
 96|     }
 97|     let bare = login.strip_suffix("[bot]").unwrap_or(login);
 98|     bare.eq_ignore_ascii_case(trimmed)
 99| }
100| 
101| /// Read back every marker tinysweeper left on a pull request.
102| ///
103| /// Errors are the caller's to decide about: this returns them rather than
104| /// swallowing them, and `review` degrades to "nothing known" so a forge outage
105| /// makes the bot repeat itself rather than go silent.
106| pub async fn load(read: &dyn ForgeRead, repo: &RepoId, number: u64) -> Result<PriorReview> {
107|     let mut prior = PriorReview::default();
108| 
109|     for comment in read.review_comments(repo, number).await? {
110|         if !is_own_login(&comment.author) {
111|             continue;
112|         }
113|         if let Some(fingerprint) = fingerprint_in(&comment.body) {
114|             // A repeated fingerprint is normal — the same finding across two
115|             // reviews — so the title is only recorded the first time.
116|             if prior.posted.insert(fingerprint)
117|                 && let Some(title) = title_in(&comment.body)
118|             {
119|                 prior.titles.push(title);
120|             }
121|         }
122|     }
123| 
124|     // The issue comments carry the state marker when a durable comment is in
125|     // use. Absent one, `last_sha` stays `None` and the caller falls back to the
126|     // review-state store; neither is required for dedupe to work.
127|     for comment in read.comments(repo, number).await? {
128|         if is_own_login(&comment.author)
129|             && let Some(sha) = marker_value(&comment.body, STATE_KEY)
130|             && is_sha(sha)
131|         {
132|             prior.last_sha = Some(sha.to_string());
133|         }
134|     }
135| 
136|     Ok(prior)
137| }
138| 
139| /// The fingerprint marker in a comment body, if it carries a well-formed one.
140| ///
141| /// Public because thread resolution reads the same marker back out of the
142| /// comment that opened a thread. It answers only "is there a well-formed
143| /// fingerprint here"; whether the body is one of *ours* is a separate question,
144| /// asked with [`is_own_login`], and both have to hold before anything acts.
145| pub fn fingerprint_in(body: &str) -> Option<String> {
146|     let value = marker_value(body, FINGERPRINT_KEY)?;
147|     is_fingerprint(value).then(|| value.to_string())
148| }
149| 
150| /// The value of the final `<!-- tinysweeper:<key><value> -->` marker in `body`.
151| ///
152| /// The last marker is authoritative because `apply` appends the renderer-added
153| /// marker after model-generated body text. This prevents a contributor from
154| /// injecting a forged marker before the renderer footer.
155| fn marker_value<'a>(body: &'a str, key: &str) -> Option<&'a str> {
156|     let opener = format!("<!-- {}{key}", crate::MARKER_PREFIX);
157|     let start = body.rfind(&opener)? + opener.len();
158|     let rest = &body[start..];
159|     let end = rest.find("-->")?;
160|     Some(rest[..end].trim())
161| }
162| 
163| /// Whether `value` is one of our fingerprints and not merely marker-shaped
164| /// text. Sixteen lowercase hex characters, exactly — see [`Finding::fingerprint`].
165| ///
166| /// [`Finding::fingerprint`]: crate::findings::Finding::fingerprint
167| fn is_fingerprint(value: &str) -> bool {
168|     value.len() == 16
169|         && value
170|             .bytes()
171|             .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
172| }
173| 
174| /// Whether `value` looks like a git object id.
175| fn is_sha(value: &str) -> bool {
176|     (7..=40).contains(&value.len()) && value.bytes().all(|b| b.is_ascii_hexdigit())
177| }
178| 
179| /// The finding title out of a comment tinysweeper wrote.
180| ///
181| /// The apply path renders `{badge} **{title}**`, so the title is the first
182| /// bold run. A body that does not match that shape simply has no title, which
183| /// costs a prompt layer-4 line and nothing else.
184| fn title_in(body: &str) -> Option<String> {
185|     let start = body.find("**")? + 2;
186|     let rest = &body[start..];
187|     let end = rest.find("**")?;
188|     let title = rest[..end].trim();
189|     (!title.is_empty()).then(|| title.to_string())
190| }
