542|     async fn commit_patch(&self, repo: &RepoId, sha: &str) -> Result<Option<String>> {
543|         // The commit endpoint carries per-file patches. Assembled here into one
544|         // unified text rather than requested as `application/vnd.github.diff`,
545|         // because the JSON shape lets each file be capped on the way in: a
546|         // vendored directory landing in one commit must not pull megabytes into
547|         // memory before anything gets to truncate it.
548|         let route = format!("/repos/{}/{}/commits/{sha}", repo.owner, repo.name);
549|         let raw: serde_json::Value = match self.client.get(&route, None::<&()>).await {
550|             Ok(raw) => raw,
551|             // A commit the forge will not render a diff for is not an error.
552|             Err(octocrab::Error::GitHub { source, .. }) if source.status_code == 404 => {
553|                 return Ok(None);
554|             }
555|             Err(err) => return Err(api(err)),
556|         };
557| 
558|         let Some(files) = raw["files"].as_array() else {
559|             return Ok(None);
560|         };
561| 
562|         let mut patch = String::new();
563|         for file in files {
564|             let path = file["filename"].as_str().unwrap_or_default();
565|             let Some(hunks) = file["patch"].as_str() else {
566|                 // No patch means binary, or a file GitHub truncated. Named
567|                 // anyway: "this commit touched a binary" is evidence, and
568|                 // silence would read as "it touched nothing".
569|                 let status = file["status"].as_str().unwrap_or("changed");
570|                 patch.push_str(&format!("--- {path} ({status}, no textual patch)\n"));
571|                 continue;
572|             };
573|             patch.push_str(&format!("--- a/{path}\n+++ b/{path}\n"));
574|             patch.push_str(truncate_patch(hunks, MAX_FILE_PATCH_BYTES).trim_end());
575|             patch.push('\n');
576|         }
577| 
578|         Ok((!patch.is_empty()).then_some(patch))
579|     }
