125|                 &request.schema_name,
126|                 request.schema.clone(),
127|             )),
128|             ..RunPolicy::default()
129|         });
130| 
131|         let messages: Vec<TaMessage> = request
132|             .messages
133|             .iter()
134|             .map(|m| match m.role {
135|                 Role::System => TaMessage::system(&m.content),
136|                 Role::User => TaMessage::user(&m.content),
137|                 Role::Assistant => TaMessage::assistant(&m.content),
138|             })
139|             .collect();
140| 
