142|         // is where the output ceiling lives — see [`run_config`].
143|         let run = harness
144|             .invoke(&(), (), run_config(request), messages)
145|             .await
146|             .map_err(|err| Error::Model(format!("{model}: {err}")))?;
147| 
148|         // Structured output is not optional: a lane that falls back to parsing
149|         // prose posts nonsense the first time a model phrases something
150|         // differently.
151|         let value = run.structured.ok_or_else(|| {
152|             Error::Model(format!(
153|                 "{model} returned no structured output; the response did not satisfy the schema"
154|             ))
155|         })?;
156| 
157|         let totals = run.usage.usage;
158|         let usage = Usage {
159|             input_tokens: totals.input_tokens,
160|             output_tokens: totals.output_tokens,
161|             cached_tokens: totals.cache_read_tokens,
162|             embed_tokens: 0,
163|             cost_usd: pricing::completion_cost(
164|                 model,
165|                 totals.input_tokens,
166|                 totals.cache_read_tokens,
167|                 totals.output_tokens,
168|             ),
169|         };
170| 
171|         Ok(ModelResponse {
172|             value,
173|             model: model.to_string(),
174|             usage,
175|         })
