 1| //! The issue triage job: read, ask, decide.
 2| //!
 3| //! Read-only by construction. This module takes a [`ForgeRead`] and can no more
 4| //! post a comment than a lane can — [`crate::issues::apply`] does that, later,
 5| //! from the plan this returns. That is the same split `src/app/review.rs` makes
 6| //! and for the same reason.
 7| //!
 8| //! The order of operations is the security property. Candidates are chosen
 9| //! deterministically *before* the model is asked; the model picks from that
10| //! list; the number it picks is re-fetched from the forge; and only then does
11| //! the pure gate in [`crate::issues::close`] decide. A model that answers
12| //! "close everything" changes nothing, because the only thing it can influence
13| //! is which of a handful of real numbers is offered as evidence.
14| 
15| use std::sync::Arc;
16| 
17| use serde_json::Value;
18| 
19| use crate::config::types::Config;
20| use crate::error::{Error, Result};
21| use crate::forge::types::RepoId;
22| use crate::issues::close::{CloseInputs, CloseOutcome, Referenced};
23| use crate::issues::types::{
24|     ClaimKind, DuplicateClaim, IssueSeverity, IssueVerdict, Priority, TriagePlan,
25| };
26| use crate::issues::{close, comment, dedupe, labels, prompt};
27| use crate::ports::forge::ForgeRead;
28| use crate::ports::model::{Message, Model, ModelRequest, Spend};
29| 
30| /// How many open issues are scanned for a duplicate.
31| ///
32| /// The forge returns them most-recently-updated first, so this is a recency
33| /// window rather than a sample: a duplicate of something nobody has touched in
34| /// two years is not what triage is for.
35| pub const SCAN_LIMIT: usize = 200;
36| 
37| /// How many candidates are put in front of the model.
38| pub const MAX_CANDIDATES: usize = 5;
39| 
40| /// What one triage run concluded.
41| #[derive(Debug, Clone)]
42| pub struct TriageOutcome {
43|     /// What deterministic code decided to do. The only thing `apply` reads.
44|     pub plan: TriagePlan,
45|     /// What the model said. Advisory, kept for the log and for tests.
46|     pub verdict: IssueVerdict,
47|     /// Model spend for the run.
48|     pub spend: Spend,
49|     /// Why nothing happened, when nothing did.
50|     pub skipped: Option<&'static str>,
51| }
52| 
53| /// Triage one issue and return a plan. Writes nothing.
54| pub async fn triage(
55|     forge: &dyn ForgeRead,
56|     model: Arc<dyn Model>,
57|     config: &Config,
58|     repo: &RepoId,
59|     number: u64,
60|     maintainers: &[String],
61| ) -> Result<TriageOutcome> {
62|     let policy = &config.issues;
63|     if !policy.enabled {
64|         return Ok(skipped("issues.enabled is off"));
65|     }
66| 
67|     let issue = forge.issue(repo, number).await?;
68|     if !issue.open {
69|         return Ok(skipped("the issue is already closed"));
70|     }
71| 
72|     // The shortlist is built before the model is asked, and its numbers are the
73|     // only ones the close gate will later accept. Everything downstream of here
74|     // is bounded by this list.
75|     let candidates = if policy.dedupe {
76|         let others = forge.open_issues(repo, SCAN_LIMIT).await?;
77|         dedupe::shortlist(&issue, &others, MAX_CANDIDATES)
78|     } else {
79|         Vec::new()
80|     };
81| 
82|     let comments = forge.comments(repo, number).await?;
