290| /// The sandboxed extractor.
291| ///
292| /// Holds the cheap model and the content-hash cache. It is given a forge per
293| /// call rather than at construction so one extractor serves every repository.
294| pub struct Extractor<'a> {
295|     model: &'a dyn Model,
296|     model_id: String,
297|     max_bytes: usize,
298|     cache: RuleCache,
299| }
300| 
301| impl<'a> Extractor<'a> {
302|     /// An extractor running on `model_id`, which must be the cheap tier.
303|     ///
304|     /// The tier is the caller's choice only in the sense that it reads it out
305|     /// of `config.models.scan`. Running extraction on the deep tier would pay
306|     /// review prices for a summarisation job.
307|     pub fn new(model: &'a dyn Model, model_id: impl Into<String>, max_bytes: usize) -> Self {
308|         Self {
309|             model,
310|             model_id: model_id.into(),
311|             max_bytes,
312|             cache: RuleCache::global(),
313|         }
314|     }
315| 
316|     /// Use `cache` instead of the process-wide one. For tests.
317|     pub fn with_cache(mut self, cache: RuleCache) -> Self {
318|         self.cache = cache;
319|         self
320|     }
321| 
322|     /// Extract rules from every scoped file at `head_sha`.
323|     ///
324|     /// Best-effort by construction: a file that cannot be fetched, a model that
325|     /// errors and an answer that fails validation all contribute nothing and
326|     /// none of them fail the review. Repository policy is an *improvement* to a
327|     /// review, and losing a review over it would be a worse outcome than
328|     /// reviewing without it — and a way for any contributor to break the bot.
329|     pub async fn extract(
330|         &self,
331|         forge: &dyn ForgeRead,
332|         repo: &RepoId,
333|         head_sha: &str,
334|         files: &[String],
335|     ) -> (Vec<String>, Usage) {
336|         let mut rules: Vec<String> = Vec::new();
337|         let mut usage = Usage::default();
338| 
339|         for path in files {
340|             let file = match self.fetch(forge, repo, head_sha, path).await {
341|                 Ok(Some(file)) => file,
342|                 Ok(None) => continue,
343|                 Err(err) => {
344|                     tracing::warn!(%err, %path, "could not read an instruction file");
345|                     continue;
346|                 }
347|             };
348| 
349|             if let Some(cached) = self.cache.get(&file.content_hash) {
350|                 tracing::debug!(%path, "extraction served from the content-hash cache");
351|                 merge(&mut rules, cached);
352|                 continue;
353|             }
354| 
355|             match self.extract_one(&file).await {
356|                 Ok((extracted, call_usage)) => {
357|                     usage.add(call_usage);
358|                     self.cache.put(&file.content_hash, extracted.clone());
359|                     merge(&mut rules, extracted);
360|                 }
361|                 Err(err) => tracing::warn!(%err, %path, "extraction failed; ignoring the file"),
362|             }
363| 
364|             if rules.len() >= MAX_RULES {
365|                 break;
366|             }
367|         }
368| 
369|         rules.truncate(MAX_RULES);
370|         (rules, usage)
371|     }
372| 
373|     /// Fetch one instruction file at `head_sha`, truncated and hashed.
374|     async fn fetch(
375|         &self,
376|         forge: &dyn ForgeRead,
377|         repo: &RepoId,
378|         head_sha: &str,
379|         path: &str,
380|     ) -> Result<Option<InstructionFile>> {
381|         // Validated again here rather than trusted from the caller: this is the
382|         // function that turns a name into a request, so it is the function that
383|         // has to be safe on its own.
384|         if !crate::knowledge::types::valid_instruction_path(path) {
385|             tracing::warn!(%path, "refusing to fetch an instruction file with an unsafe path");
386|             return Ok(None);
387|         }
388| 
389|         let Some(content) = forge.file_at(repo, path, head_sha).await? else {
390|             return Ok(None);
391|         };
392|         let content = truncate_bytes(&content, self.max_bytes).to_string();
393|         if content.trim().is_empty() {
394|             return Ok(None);
395|         }
396| 
397|         Ok(Some(InstructionFile {
398|             content_hash: content_hash(&content),
399|             path: path.to_string(),
400|             content,
401|         }))
402|     }
403| 
404|     /// The model calls for one file. No review context, and at most
405|     /// [`EXTRACT_ATTEMPTS`] of them.
406|     ///
407|     /// The retry is on the *format*, never on the content: an answer that
408|     /// parses is taken as it stands, and so is the `NO_RULES` sentinel, which is
409|     /// a correct answer rather than a failed one. Asking again for a file that
410|     /// genuinely states no rules would pay a second call for the same "no".
411|     ///
412|     /// A model *error* is not retried here — the gateway already walks its
413|     /// fallback models — and it costs the file rather than the review.
414|     async fn extract_one(&self, file: &InstructionFile) -> Result<(Vec<String>, Usage)> {
415|         let mut usage = Usage::default();
416| 
417|         for attempt in 1..=EXTRACT_ATTEMPTS {
418|             let response = self.call(file).await?;
419|             usage.add(response.usage);
420| 
421|             let raw = response
422|                 .value
423|                 .get("rules_markdown")
424|                 .and_then(serde_json::Value::as_str)
425|                 .unwrap_or_default();
426| 
427|             let rules = parse_rules(raw);
428|             if !rules.is_empty() || raw.trim() == NO_RULES {
429|                 return Ok((rules, usage));
430|             }
431| 
432|             tracing::warn!(
433|                 path = %file.path,
434|                 attempt,
435|                 "an extraction was discarded; asking again"
436|             );
437|         }
438| 
439|         Ok((Vec::new(), usage))
440|     }
441| 
442|     /// One extraction request. Identical on every attempt: the retry exists to
443|     /// re-roll a model that slipped its format, and rewriting the prompt between
444|     /// attempts would mean the answer that lands was produced by a prompt no
445|     /// test covers.
446|     async fn call(&self, file: &InstructionFile) -> Result<crate::ports::model::ModelResponse> {
447|         self.model
448|             .complete(ModelRequest {
449|                 model: self.model_id.clone(),
450|                 messages: vec![
451|                     Message::system(EXTRACT_SYSTEM),
452|                     // The file is fenced and labelled here too. The system
453|                     // prompt says the input is documentation; the fence is what
454|                     // makes "the input" a thing with edges.
455|                     Message::user(user_message(file)),
456|                 ],
457|                 schema: extract_schema(),
458|                 schema_name: "tinysweeper_rule_extraction".into(),
459|                 max_tokens: EXTRACT_MAX_TOKENS,

