  1| //! The `description` lane: does the pull request say what it does?
  2| //!
  3| //! The one lane whose subject has no line number. A missing body, a title that
  4| //! describes a bugfix over a diff that adds a dependency, a "Fixes #123" that
  5| //! points at an unrelated issue — none of these live at `src/foo.rs:42`. So
  6| //! this lane's findings are allowed to arrive without an anchor and be rendered
  7| //! in the check-run summary instead of as an inline comment. See
  8| //! `lanes::anchor` for the rule.
  9| //!
 10| //! An empty body is decided **deterministically**, before any model call. It is
 11| //! a fact about the pull request, a model adds nothing to it, and paying for a
 12| //! model to observe that a string is empty is money for a foregone conclusion.
 13| 
 14| use std::sync::Arc;
 15| 
 16| use async_trait::async_trait;
 17| 
 18| use crate::config::types::{LaneId, Severity};
 19| use crate::error::Result;
 20| use crate::evidence::diff::render as render_diffs;
 21| use crate::findings::types::Finding;
 22| use crate::forge::types::PullRequest;
 23| use crate::harness::prompt::{self, PromptInputs};
 24| use crate::harness::schema;
 25| use crate::lanes::{Anchoring, Lane, LaneInput, LaneOutcome};
 26| use crate::ports::model::{Message, Model, ModelRequest, Spend};
 27| 
 28| /// Bodies shorter than this are treated as no body at all.
 29| ///
 30| /// "wip", "." and "asdf" are not descriptions, and a length check catches them
 31| /// without a model call. Deliberately small: a one-line description of a
 32| /// one-line change is fine, and the lane is not a word-count enforcer.
 33| const MIN_BODY_CHARS: usize = 12;
 34| 
 35| /// The "path" a finding about the description itself carries.
 36| const DESCRIPTION_SUBJECT: &str = "(pull request description)";
 37| 
 38| /// The description lane.
 39| pub struct Description {
 40|     model: Arc<dyn Model>,
 41| }
 42| 
 43| impl Description {
 44|     /// Build the lane over `model`.
 45|     pub fn new(model: Arc<dyn Model>) -> Self {
 46|         Self { model }
 47|     }
 48| }
 49| 
 50| #[async_trait]
 51| impl Lane for Description {
 52|     fn id(&self) -> LaneId {
 53|         LaneId::Description
 54|     }
 55| 
 56|     async fn run(&self, input: LaneInput<'_>) -> Result<LaneOutcome> {
 57|         if !input.has_reviewable_content() {
 58|             return Ok(LaneOutcome::skipped(
 59|                 "No added or modified lines to review.",
 60|             ));
 61|         }
 62| 
 63|         if let Some(skipped) = input.skip_as_draft() {
 64|             return Ok(skipped);
 65|         }
 66| 
 67|         let pr = input.pull_request;
 68|         if pr.body.trim().chars().count() < MIN_BODY_CHARS {
 69|             return Ok(empty_body_outcome(pr, input.diffs.len()));
 70|         }
 71| 
 72|         let changed_paths = input.changed_paths();
 73| 
 74|         // Split, rather than sending the whole diff alongside a replay of it.
 75|         // Passing both — which this did — puts every previously reviewed line
 76|         // in the prompt twice, so a re-review cost *more* than the first.
 77|         let rendered = render_diffs(input.diffs);
 78|         let (reviewed_evidence, evidence) =
 79|             crate::evidence::replay::split(input.reviewed_evidence, &rendered);
 80|         let pull_request_text = render_pull_request(pr);
 81| 
 82|         let built = prompt::build(&PromptInputs {
 83|             repo_policy: input.repo_policy,
 84|             extracted_rules: input.extracted_rules,
 85|             reviewed_evidence: &reviewed_evidence,
 86|             prior_findings: input.prior_findings,
 87|             new_evidence: &evidence,
 88|             changed_paths: &changed_paths,
 89|             pull_request_text: &pull_request_text,
 90|             ..PromptInputs::new(LaneId::Description, input.config)
 91|         });
 92| 
 93|         let response = self
 94|             .model
 95|             .complete(ModelRequest {
 96|                 model: input.config.model_for(LaneId::Description).to_string(),
 97|                 messages: vec![
 98|                     Message::system(built.prefix()),
 99|                     Message::user(built.suffix()),
100|                 ],
101|                 schema: schema::json_schema(),
102|                 schema_name: "tinysweeper_description".into(),
103|                 max_tokens: input.config.models.max_tokens,

